        IF spec->>'table' NOT IN ('topic_references') THEN
            RAISE EXCEPTION 'Unexpected table';
        END IF;
        locator := format('SELECT to_jsonb(t) FROM public.%I t WHERE id = $1',spec->>'table');
        EXECUTE locator || ' FOR UPDATE' INTO STRICT original USING (spec->>'id')::uuid;
        IF spec->>'table' = 'podcasts' THEN
            IF jsonb_build_object('topic_id',original->'topic_id','script_md5',md5(original->>'script'),
                  'audio_path_md5',md5(original->>'audio_path'),'regenerating',original->'regenerating') IS DISTINCT FROM spec->'guard' THEN
                RAISE EXCEPTION 'Stale recording, asset, topic or generation state: %',spec->>'id';
            END IF;
        ELSIF NOT (original @> (spec->'guard')) THEN
            RAISE EXCEPTION 'Row identity changed: %',spec->>'id';
        END IF;
        proposed := original;
        old_matches := true;
        new_matches := true;
        FOR item IN SELECT value FROM jsonb_array_elements(spec->'edits') LOOP
            target := ARRAY(SELECT jsonb_array_elements_text(item->'path'));
            old_matches := old_matches AND ((original #> target) IS NOT DISTINCT FROM (item->'before'));
            new_matches := new_matches AND ((original #> target) IS NOT DISTINCT FROM (item->'after'));
            proposed := jsonb_set(proposed, target, item->'after', false);
        END LOOP;
        
        IF new_matches THEN CONTINUE; END IF;
        IF NOT old_matches THEN
            RAISE EXCEPTION 'Stale, missing or partially changed audited values: %.%',spec->>'table',spec->>'id';
        END IF;
        SELECT string_agg(format('%1$I = (jsonb_populate_record(NULL::public.%2$I,$1)).%1$I',field,spec->>'table'), ', ' ORDER BY field)
          INTO assignments FROM (SELECT DISTINCT e->'path'->>0 AS field FROM jsonb_array_elements(spec->'edits') e) columns_to_change;
        EXECUTE format('UPDATE public.%I SET %s WHERE id=$2',spec->>'table',assignments)
          USING proposed, (spec->>'id')::uuid;
        GET DIAGNOSTICS affected = ROW_COUNT;
        IF affected <> 1 THEN RAISE EXCEPTION 'Expected to update one row: %',spec->>'id'; END IF;
        EXECUTE locator INTO STRICT reread USING (spec->>'id')::uuid;
        FOR item IN SELECT value FROM jsonb_array_elements(spec->'edits') LOOP
            target := ARRAY(SELECT jsonb_array_elements_text(item->'path'));
            IF (reread #> target) IS DISTINCT FROM (item->'after') THEN
                RAISE EXCEPTION 'Read-back failed: % %',spec->>'id',target;
            END IF;
        END LOOP;
    END LOOP;
END;
